class DetailPelangganScreen extends StatefulWidget{final Pelanggan pelanggan;const DetailPelangganScreen({super.key,required this.pelanggan});@override State<DetailPelangganScreen> createState()=>_DetailState();}
class _DetailState extends State<DetailPelangganScreen>{List<TransaksiKredit> rows=[];bool loading=true;@override void initState(){super.initState();_load();}Future<void> _load()async{final r=await context.read<PiutangProvider>().muatTransaksi(widget.pelanggan.id!);if(mounted)setState((){rows=r;loading=false;});}
Future<void> _transaksi()async{final key=GlobalKey<FormState>();final res=TextEditingController(),recv=TextEditingController(),city=TextEditingController(),amount=TextEditingController(),note=TextEditingController();DateTime date=DateTime.now();bool saving=false;await showModalBottomSheet(context:context,isScrollControlled:true,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>Padding(padding:EdgeInsets.fromLTRB(16,8,16,MediaQuery.of(ctx).viewInsets.bottom+12),child:SingleChildScrollView(child:Form(key:key,child:Column(children:[Text('Tambah Transaksi Kredit',style:Theme.of(ctx).textTheme.titleLarge),TextFormField(controller:res,decoration:const InputDecoration(labelText:'Nomor Resi *'),validator:(v)=>v!.trim().isEmpty?'Wajib diisi':null),TextFormField(controller:recv,decoration:const InputDecoration(labelText:'Nama Penerima *'),validator:(v)=>v!.trim().isEmpty?'Wajib diisi':null),TextFormField(controller:city,decoration:const InputDecoration(labelText:'Kota Tujuan *'),validator:(v)=>v!.trim().isEmpty?'Wajib diisi':null),TextFormField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Jumlah *'),validator:(v)=>int.tryParse(v!.replaceAll('.',''))==null?'Jumlah tidak valid':null),TextField(controller:note,decoration:const InputDecoration(labelText:'Catatan')),ListTile(title:Text(Formatter.tanggalPanjang(date)),trailing:const Icon(Icons.calendar_today),onTap:()async{final d=await showDatePicker(context:ctx,firstDate:DateTime(2000),lastDate:DateTime(2100),initialDate:date);if(d!=null)set(()=>date=d);}),ElevatedButton(onPressed:saving?null:()async{if(!key.currentState!.validate())return;set(()=>saving=true);try{await ctx.read<PiutangProvider>().tambahTransaksi(TransaksiKredit(pelangganId:widget.pelanggan.id!,tanggal:date,nomorResi:res.text.trim(),namaPenerima:recv.text.trim(),kotaTujuan:city.text.trim(),jumlah:int.parse(amount.text.replaceAll('.','')),catatan:note.text.trim().isEmpty?null:note.text.trim()));if(ctx.mounted)Navi